const earning_card_style_style = scoped.css `
  section {
    padding: 8px 12px;
  }

  .counter {
    padding: 24px 16px 16px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 20px;

    img {
      width: auto;
      height: 87px;
    }
  }

  .counter-text {
    font: ${font.default.regular};
    color: ${color.text.tertiary};
    text-align: center;
    min-height: 80px;
    display: flex;
    flex-direction: column;
    align-items: center;
  }

  .counter-value {
    --leo-icon-size: 14px;

    position: relative;
    font: ${font.heading.h2};
    color: ${color.text.primary};

    leo-tooltip {
      position: absolute;
      inset-inline-start: calc(100% + 6px);
      inset-block-start: 4px;

      [slot=content] {
        max-width: 250px;
        text-align: start;
      }
    }
  }

  .connect {
    display: flex;
    align-items: center;
    gap: 8px;

    leo-button {
      flex: 0 0 auto;
    }
  }

  .connect-text {
    flex: 1 1 auto;
    color: ${color.text.primary};
    font: ${font.default.semibold};
  }

  .connect-subtext {
    font: ${font.small.regular};
    opacity: 0.6;
  }

  .ads-summary {
    display: flex;
    flex-direction: column;
    gap: 8px;
  }

  .ads-summary-title {
    font: ${font.default.semibold};
    cursor: pointer;
    display: flex;
    align-items: center;

    .value {
      background:
        linear-gradient(314deg, #3C823C 8.49%, #2ABA32 48.32%, #94DF91 99.51%);
      background-clip: text;
      -webkit-text-fill-color: transparent;
      padding-inline-end: 4px;
    }

    > :first-child {
      flex: 1 0 auto;
    }
  }

  .ads-summary-nav {
    --leo-icon-size: 16px;

    display: flex;
    justify-content: space-between;
    gap: 4px;

    button {
      font: ${font.components.buttonSmall};
      color: ${color.text.secondary};
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 4px 0;
    }

    .unconnected & {
      margin-top: 12px;
      padding-top: 8px;
      border-top: solid 1px ${color.divider.subtle};
    }
  }

  .warning-box {
    --leo-icon-size: 20px;
    --leo-icon-color: ${color.systemfeedback.warningIcon};

    color: ${color.systemfeedback.warningText};
    background: ${color.systemfeedback.warningBackground};
    padding: 16px;
    border-radius: 12px;
    font: ${font.default.regular};
    display: flex;
    gap: 16px;
    align-items: center;
  }
`;

